(* [comment removed for export] *)
Lemma w4s34_else : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
    (P DT4 DBL DBH DST dcap tl SS n SBL SBH S4 L4 PTR BITS PP : Z) (cells : list deltX1) (w240 w248 : word),
  w4s34_ctx RNG mm P DT4 DBL DBH DST dcap tl SS n SBL SBH S4 cells -> mem_inv asegs mm ->
  rw_cells asegs mm (P + 240) [C8 w240] -> rw_cells asegs mm (P + 248) [C4 w248] ->
  rw_cells asegs mm (P + 256) [C8 (Z_to_bv 64 PTR)] -> n < 2^26 -> KXGoM.apart SS n P 496 ->
  SS <= S4 -> S4 + L4 <= SS + n -> 8 <= S4 -> S4 + 16 <= 2^47 ->
  S4 <= PTR -> (PTR = S4 \/ PTR + 8 <= S4 + L4) -> 0 <= BITS < 2^31 ->
  (forall (mm' : amem) (c240 w248' w256' y5 y6 y11 y14 y15 y17 : word),
     munch [(P + 240, P + 252); (P + 256, P + 264)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     rw_cells asegs mm' (P + 240) [C8 c240] -> rw_cells asegs mm' (P + 248) [C4 w248'] ->
     rw_cells asegs mm' (P + 256) [C8 w256'] ->
     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp y5 y6 x7 x8 x9 x10 y11 x12 x13 y14 y15 (Z_to_bv 64 PP) y17 x18 x19
          x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x92d7c) fc None mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 (Z_to_bv 64 BITS) (Z_to_bv 64 PP)
