(* [comment removed for export] *)
Lemma w4s34_all : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (gp tp x5 x6 x7 x8 x10 x11 x12 x13 x14 x15 x17 x18 x19 x20 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
    (P DT4 DBL DBH DST dcap tl mtl PE OL SS n SBL SBH S4 L4 PTR B PP : Z) (cells : list deltX1) (obuf : list Z)
    (w240 : word),
  w4s34_ctx RNG mm P DT4 DBL DBH DST dcap tl SS n SBL SBH S4 cells -> mem_inv asegs mm ->
  x1_table_ok cells tl -> u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
  rw_cells asegs mm (P + 240) [C8 w240] -> rw_cells asegs mm (P + 248) [C4 (Z_to_bv 64 B)] ->
  rw_cells asegs mm (P + 256) [C8 (Z_to_bv 64 PTR)] ->
  n < 2^26 -> KXGoM.apart SS n P 496 -> KXGoM.apart DST dcap SS n -> 1 <= n ->
  SS <= S4 -> S4 + L4 <= SS + n -> 8 <= S4 -> S4 + 16 <= 2^47 ->
  S4 <= PTR -> (PTR = S4 \/ PTR + 8 <= S4 + L4) -> 0 <= B < 2^31 ->
  DST <= PP <= PE -> PE = OL + 3 -> PE <= DST + dcap -> DST + dcap < 2^47 -> 1 <= dcap <= 2^32 -> 1 <= mtl <= 12 ->
  (forall (mm' : amem) (c240 w248' w256' y5 y6 y7 y11 y14 y15 y16 y17 y28 y29 y30 y31 : word),
     munch [(DST, DST + dcap); (P + 240, P + 252); (P + 256, P + 264)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
     rw_cells asegs mm' (P + 240) [C8 c240] -> rw_cells asegs mm' (P + 248) [C4 w248'] ->
     rw_cells asegs mm' (P + 256) [C8 w256'] ->
     evtF asegs RNG Q (MS (mkR (Z_to_bv 64 OL) (Z_to_bv 64 P) gp tp y5 y6 y7 x8 (Z_to_bv 64 PE) x10 y11 x12 x13 y14 y15 y16
          y17 x18 x19 x20 (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 DT4) x23 x24 x25 x26 x27 y28 y29 y30 y31) F
          (Z_to_bv 64 0x92e2c) fc None mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR (Z_to_bv 64 OL) (Z_to_bv 64 P) gp tp x5 x6 x7 x8 (Z_to_bv 64 PE) x10 x11 x12 x13 x14 x15
      (Z_to_bv 64 PP) x17 x18 x19 x20 (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 DT4) x23 x24 x25 x26 x27 x28 x29 x30
